def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Bridge pairs of interior dots on the same column, excluding border bars.
    for c in range(w):
        rows = [r for r in range(1, h - 1)
                if grid[r][c] not in (bg, 8) and
                (c == 0 or grid[r][c-1] == bg) and
                (c == w-1 or grid[r][c+1] == bg)]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

