def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Fill between successive foreground marks on each row.
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] != bg]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # Fill vertical gaps using marks that are isolated horizontally, so a
    # horizontal bar cannot act as an endpoint of a long vertical stroke.
    for c in range(w):
        marks = []
        for r in range(h):
            if grid[r][c] == bg:
                continue
            has_horizontal_neighbor = ((c > 0 and grid[r][c - 1] != bg) or
                                       (c + 1 < w and grid[r][c + 1] != bg))
            if not has_horizontal_neighbor:
                marks.append(r)
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

