def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Highlight background cells immediately adjacent to the outline's foreground.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                continue
            if any(0 <= rr < h and 0 <= cc < w and grid[rr][cc] != bg
                   for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                out[r][c] = 2
    return out
